import sys
import csv

REQUIRED = ['department', 'category', 'amount', 'status']

def parse_cents(s):
    if s == '':
        return None
    neg = False
    if s[0] == '-':
        neg = True
        s = s[1:]
        if s == '':
            return None
    parts = s.split('.')
    if len(parts) > 2:
        return None
    dollars = parts[0]
    if dollars == '' or not dollars.isdigit():
        return None
    frac = ''
    if len(parts) == 2:
        frac = parts[1]
        if frac == '' or len(frac) > 2 or not frac.isdigit():
            return None
    frac = (frac + '00')[:2]
    cents = int(dollars) * 100 + int(frac)
    return -cents if neg else cents

def money(cents):
    sign = '-' if cents < 0 else ''
    cents = abs(cents)
    return f"{sign}{cents // 100}.{cents % 100:02d}"

