import sys

def main():
    data = sys.stdin.read().splitlines()
    if len(data) < 5:
        return
    base = data[0].rstrip('/')
    default_ext = data[1].strip().lower()
    m = int(data[2].strip())
    allowed_line = data[3].strip()
    allowed = set()
    if m:
        allowed = {x.lower() for x in allowed_line.split()}
    n = int(data[4].strip())
    paths = data[5:5+n]
    out = []
    for raw in paths:
        s = raw.strip().replace('\\', '/')
        cut_positions = [p for p in (s.find('?'), s.find('#')) if p != -1]
        if cut_positions:
            s = s[:min(cut_positions)]
        comps = []
        invalid = False
        for part in s.split('/'):
            if part == '' or part == '.':
                continue
            if part == '..':
                if comps:
                    comps.pop()
                else:
                    invalid = True
                    break
            else:
                comps.append(part)
        if invalid or not comps:
            out.append('INVALID')
            continue
        name = comps[-1]
        dot = name.rfind('.')
        has_ext = dot > 0 and dot < len(name) - 1
        if not has_ext:
            name = name + '.' + default_ext
        else:
            stem = name[:dot]
            ext = name[dot+1:].lower()
            if ext not in allowed:
                ext = default_ext
            name = stem + '.' + ext
        comps[-1] = name
        out.append(base + '/' + '/'.join(comps))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))

if __name__ == '__main__':
    main()

import sys
from urllib.parse import urlsplit


def strip_qf(s):
    q = s.find('?')
    h = s.find('#')
    cuts = [x for x in (q, h) if x != -1]
    return s[:min(cuts)] if cuts else s


def norm_path(p):
    parts = []
    for seg in p.split('/'):
        if seg == '' or seg == '.':
            continue
        if seg == '..':
            if parts:
                parts.pop()
        else:
            parts.append(seg)
    return '/' + '/'.join(parts)


def base_dir(path):
    if not path:
        return '/'
    if path.endswith('/'):
        return path
    i = path.rfind('/')
    if i < 0:
        return '/'
    return path[:i+1]


def main():
    data = sys.stdin.read().splitlines()
    if len(data) < 3:
        return
    base = data[0].strip()
    allowed = set(x.strip().lower() for x in data[1].split(',') if x.strip() != '')
    n = int(data[2].strip())
    refs = data[3:3+n]
    b = urlsplit(base)
    b_scheme = b.scheme
    b_netloc = b.netloc
    b_path = b.path if b.path else '/'
    b_dir = base_dir(b_path)
    out = []
    for raw in refs:
        ref = strip_qf(raw.strip())
        if ref == '':
            out.append('SKIP empty')
            continue
        path = None
        if ref.startswith('//'):
            u = urlsplit(b_scheme + ':' + ref)
            if u.scheme.lower() != b_scheme.lower() or u.netloc.lower() != b_netloc.lower():
                out.append('SKIP external')
                continue
            path = u.path if u.path else '/'
        else:
            u = urlsplit(ref)
            if u.scheme != '' or u.netloc != '':
                if u.scheme.lower() != b_scheme.lower() or u.netloc.lower() != b_netloc.lower():
                    out.append('SKIP external')
                    continue
                path = u.path if u.path else '/'
            elif ref.startswith('/'):
                path = ref
            else:
                path = b_dir + ref
        path = norm_path(path)
        filename = path.rsplit('/', 1)[-1]
        dot = filename.rfind('.')
        if dot <= 0:
            out.append('SKIP no_extension')
            continue
        ext = filename[dot+1:].lower()
        if ext not in allowed:
            out.append('SKIP blocked_extension')
            continue
        out.append('OK ' + b_scheme + '://' + b_netloc + path)
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))

