import sys
from urllib.parse import urlsplit

ALLOWED = {'.css', '.js', '.png', '.jpg'}

def norm_path(p):
    parts = []
    for seg in p.split('/'):
        if seg == '' or seg == '.':
            continue
        if seg == '..':
            if parts:
                parts.pop()
        else:
            parts.append(seg)
    return '/' + '/'.join(parts)

def base_dir(path):
    if path.endswith('/'):
        return path
    i = path.rfind('/')
    return path[:i+1] if i >= 0 else '/'

def split_ref_query_fragment(s):
    cut = len(s)
    for ch in ('?', '#'):
        j = s.find(ch)
        if j != -1 and j < cut:
            cut = j
    return s[:cut]

def process(ref, base):
    if ref == '':
        return 'REJECT EMPTY'
    if '\\' in ref:
        return 'REJECT MALFORMED'
    ref_path_part = split_ref_query_fragment(ref)
    scheme = base.scheme.lower()
    host = base.netloc.lower()
    if '://' in ref:
        u = urlsplit(ref)
        if u.scheme.lower() not in ('http', 'https') or not u.netloc:
            return 'REJECT MALFORMED'
        scheme = u.scheme.lower()
        host = u.netloc.lower()
        raw_path = u.path
    else:
        raw = ref_path_part
        if raw.startswith('/'):
            raw_path = raw
        else:
            raw_path = base_dir(base.path) + raw
    path = norm_path(raw_path)
    if not path.startswith('/assets/'):
        return 'REJECT OUTSIDE_ASSETS'
    name = path.rsplit('/', 1)[-1]
    dot = name.rfind('.')
    if dot <= 0:
        return 'REJECT BAD_EXTENSION'
    ext = name[dot:].lower()
    if ext not in ALLOWED:
        return 'REJECT BAD_EXTENSION'
    if name[dot:] != ext:
        path = path[:len(path)-len(name)] + name[:dot] + ext
    return 'OK ' + scheme + '://' + host + path

def main():
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        return
    base = urlsplit(data[0])
    n = int(data[1])
    out = []
    for i in range(n):
        ref = data[2+i] if 2+i < len(data) else ''
        out.append(process(ref, base))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))

if __name__ == '__main__':
    main()

import sys
from urllib.parse import urlsplit, urlunsplit, urljoin


def valid_base(u):
    if ' ' in u or '\t' in u or not u:
        return None
    try:
        p = urlsplit(u)
    except Exception:
        return None
    if p.scheme not in ('http', 'https') or not p.netloc:
        return None
    return p


def normalize_path(path):
    if path == '':
        path = '/'
    trailing = path.endswith('/')
    parts = path.split('/')
    out = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if out:
                out.pop()
        else:
            out.append(part)
    norm = '/' + '/'.join(out)
    if trailing and norm != '/':
        norm += '/'
    return norm


def apply_extension(path):
    if path.endswith('/'):
        return path + 'index.html'
    last = path.rsplit('/', 1)[-1]
    if '.' not in last:
        return path + '.html'
    return path


def resolve_one(base, ref):
    if ref == '' or ' ' in ref or '\t' in ref:
        return 'INVALID'
    try:
        rp = urlsplit(ref)
    except Exception:
        return 'INVALID'
    if rp.scheme and rp.scheme not in ('http', 'https'):
        return 'INVALID'
    try:
        joined = urljoin(urlunsplit(base), ref)
        p = urlsplit(joined)
    except Exception:
        return 'INVALID'
    if p.scheme not in ('http', 'https') or not p.netloc:
        return 'INVALID'
    path = apply_extension(normalize_path(p.path))
    return urlunsplit((p.scheme, p.netloc, path, p.query, p.fragment))


def main():
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        return
    base_line = data[0]
    try:
        n = int(data[1])
    except Exception:
        return
    refs = data[2:2+n]
    base = valid_base(base_line)
    out = []
    for ref in refs:
        if base is None:
            out.append('INVALID')
        else:
            out.append(resolve_one(base, ref))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))

if __name__ == '__main__':
    main()

