import sys
from datetime import datetime, date, time, timedelta

lines = sys.stdin.read().splitlines()
if not lines:
    sys.exit(0)

pos = 0
valid_window = True
try:
    parts = lines[pos].split()
    pos += 1
    if len(parts) != 2:
        raise ValueError
    open_t = datetime.strptime(parts[0], "%H:%M").time()
    close_t = datetime.strptime(parts[1], "%H:%M").time()
    if not (open_t < close_t):
        valid_window = False
except Exception:
    open_t = time(0, 0)
    close_t = time(0, 0)
    valid_window = False

holidays = set()
try:
    h = int(lines[pos].strip())
    pos += 1
except Exception:
    h = 0
for _ in range(max(0, h)):
    if pos >= len(lines):
        break
    s = lines[pos].strip()
    pos += 1
    try:
        holidays.add(datetime.strptime(s, "%Y-%m-%d").date())
    except Exception:
        pass

try:
    n = int(lines[pos].strip())
    pos += 1
except Exception:
    n = 0

def is_workday(d):
    return d.weekday() < 5 and d not in holidays

def at_open(d):
    return datetime.combine(d, open_t)

def at_close(d):
    return datetime.combine(d, close_t)

def next_open(dt):
    d = dt.date()
    while True:
        if is_workday(d):
            o = at_open(d)
            c = at_close(d)
            if dt < o:
                return o
            if o <= dt < c:
                return dt
        d += timedelta(days=1)
        dt = datetime.combine(d, time(0, 0))

def finish_time(start, minutes):
    cur = next_open(start)
    remaining = minutes
    if remaining == 0:
        return cur
    while True:
        c = at_close(cur.date())
        avail = int((c - cur).total_seconds() // 60)
        if remaining <= avail:
            return cur + timedelta(minutes=remaining)
        remaining -= avail
        cur = next_open(datetime.combine(cur.date() + timedelta(days=1), time(0, 0)))

out = []
for i in range(n):
    line = lines[pos] if pos < len(lines) else ""
    pos += 1
    fields = line.split()
    item_id = fields[0] if fields else "INVALID"
    try:
