        out.append(f"{item_id} {finish_time(start, dur).strftime('%Y-%m-%dT%H:%M')}")
    except Exception:
        out.append(f"{item_id} INVALID")

sys.stdout.write("\n".join(out) + ("\n" if out else ""))

