import sys
from datetime import datetime, date, time, timedelta

BUS_START = time(9, 0)
BUS_END = time(17, 0)

def parse_dt(s):
    return datetime.strptime(s, '%Y-%m-%dT%H:%M')

def parse_date(s):
    return datetime.strptime(s, '%Y-%m-%d').date()

def business_minutes(start, end, holidays):
    total = 0
    d = start.date()
    last = end.date()
    one_day = timedelta(days=1)
    while d <= last:
        if d.weekday() < 5 and d not in holidays:
            ws = datetime.combine(d, BUS_START)
            we = datetime.combine(d, BUS_END)
            a = max(start, ws)
            b = min(end, we)
            if b > a:
                total += int((b - a).total_seconds() // 60)
        d += one_day
    return total

def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        print('NONE')
        return
    try:
        first = lines[0].split()
        if len(first) != 2:
            raise ValueError
        n = int(first[0])
        h = int(first[1])
        if n < 0 or h < 0:
            raise ValueError
    except Exception:
        print('NONE')
        return

    holidays = set()
    idx = 1
    for _ in range(h):
        if idx >= len(lines):
            break
        try:
            holidays.add(parse_date(lines[idx].strip()))
        except Exception:
            pass
        idx += 1

    intervals = {}
    for _ in range(n):
        if idx >= len(lines):
            break
        parts = lines[idx].split()
        idx += 1
        if len(parts) != 3:
            continue
        emp, s, e = parts
        try:
            start = parse_dt(s)
            end = parse_dt(e)
        except Exception:
            continue
        if end <= start:
            continue
        intervals.setdefault(emp, []).append((start, end))

    results = {}
    for emp, arr in intervals.items():
        arr.sort()
        merged = []
        for s, e in arr:
            if not merged or s > merged[-1][1]:
                merged.append([s, e])
            elif e > merged[-1][1]:
                merged[-1][1] = e
        total = sum(business_minutes(s, e, holidays) for s, e in merged)
        if total > 0:
            results[emp] = total

    if not results:
        print('NONE')
    else:
        for emp in sorted(results):
            print(emp, results[emp])

