import sys


def read_count(lines, idx):
    if idx >= len(lines):
        return 0, idx
    try:
        n = int(lines[idx].strip())
        if n < 0:
            n = 0
    except ValueError:
        n = 0
    return n, idx + 1


def read_listing(lines, idx, count):
    listing = {}
    for _ in range(count):
        if idx >= len(lines):
            break
        line = lines[idx].rstrip('\n')
        idx += 1
        parts = line.split('|')
        if len(parts) != 4:
            continue
        product_id = parts[0]
        if product_id == '':
            continue
        listing[product_id] = tuple(parts[1:])
    return listing, idx


def main():
    lines = sys.stdin.readlines()
    idx = 0
    n, idx = read_count(lines, idx)
    old, idx = read_listing(lines, idx, n)
    m, idx = read_count(lines, idx)
    new, idx = read_listing(lines, idx, m)

