import sys
from urllib.parse import urlsplit

ALLOWED = {"css", "js", "png", "jpg", "svg"}

def norm_path(p):
    parts = []
    for seg in p.split('/'):
        if seg == '' or seg == '.':
            continue
        if seg == '..':
            if parts:
                parts.pop()
        else:
            parts.append(seg)
    return '/' + '/'.join(parts)

def base_dir(path):
    if not path:
        return '/'
    if path.endswith('/'):
        return path
    i = path.rfind('/')
    if i < 0:
        return '/'
    return path[:i+1]

def split_ref(s):
    q = s.find('?')
    h = s.find('#')
    ends = [x for x in (q, h) if x != -1]
    end = min(ends) if ends else len(s)
    path = s[:end]
    query = ''
    if q != -1 and (h == -1 or q < h):
        query = s[q+1: h if h != -1 else len(s)]
    return path, query

def has_allowed_ext(path):
    name = path.rsplit('/', 1)[-1]
    dot = name.rfind('.')
    if dot <= 0 or dot == len(name) - 1:
        return False
    return name[dot+1:].lower() in ALLOWED

def main():
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        return
    base = urlsplit(data[0].strip())
    try:
        n = int(data[1].strip())
    except ValueError:
        n = 0
    bdir = base_dir(base.path)
    prefix = base.scheme + '://' + base.netloc
    out = []
    for i in range(n):
        raw = data[2+i] if 2+i < len(data) else ''
        ref = raw.strip()
        idx = str(i + 1)
        if ref == '':
            out.append(idx + '\tINVALID_EMPTY')
            continue
        if '://' in ref:
            out.append(idx + '\tINVALID_REF')
            continue
        rpath, query = split_ref(ref)
        if rpath.startswith('/'):
            joined = rpath
        else:
            joined = bdir + rpath
        path = norm_path(joined)
        if not has_allowed_ext(path):
            out.append(idx + '\tINVALID_EXT\t' + path)
            continue
        url = prefix + path
        if query != '':
            url += '?' + query
        out.append(idx + '\t' + url)
    sys.stdout.write('\n'.join(out))
    if out:
        sys.stdout.write('\n')

