import sys

MAX_ADDR = (1 << 32) - 1

def parse_ip(s):
    parts = s.split('.')
    if len(parts) != 4:
        return None
    value = 0
    for part in parts:
        if part == '' or not part.isdigit():
            return None
        n = int(part)
        if n < 0 or n > 255:
            return None
        value = value * 256 + n
    return value

def parse_cidr(line):
    stripped = line.strip()
    fields = stripped.split()
    if len(fields) != 1:
        return None
    token = fields[0]
    if token.count('/') != 1:
        return None
    ip_s, pref_s = token.split('/')
    if pref_s == '' or not pref_s.isdigit():
        return None
    p = int(pref_s)
    if p < 0 or p > 32:
        return None
    ip = parse_ip(ip_s)
    if ip is None:
        return None
    size = 1 << (32 - p)
    start = (ip // size) * size
    end = start + size - 1
    return (start, end)

def ip_to_str(x):
    a = x // (256 * 256 * 256)
    x %= 256 * 256 * 256
    b = x // (256 * 256)
    x %= 256 * 256
    c = x // 256
    d = x % 256
    return str(a) + '.' + str(b) + '.' + str(c) + '.' + str(d)

def interval_to_cidrs(start, end):
    out = []
    cur = start
    while cur <= end:
        remaining = end - cur + 1
        if cur == 0:
            block = 1 << 32
        else:
            block = cur & -cur
        while block > remaining:
            block //= 2
        prefix = 32 - (block.bit_length() - 1)
        out.append((cur, prefix))
        cur += block
    return out

def main():
    data = sys.stdin.read().splitlines()
    if not data or data[0].strip() == '' or not data[0].strip().isdigit():
        print('VALID 0')
        print('INVALID 0')
        return
    n = int(data[0].strip())
    lines = data[1:1+n]
    intervals = []
    invalid = 0
    for line in lines:
        parsed = parse_cidr(line)
        if parsed is None:
            invalid += 1
        else:
            intervals.append(parsed)
    intervals.sort()
    merged = []
    for s, e in intervals:
        if not merged or s > merged[-1][1] + 1:
            merged.append([s, e])
        else:
            if e > merged[-1][1]:
                merged[-1][1] = e
    cidrs = []
    for s, e in merged:
        cidrs.extend(interval_to_cidrs(s, e))
    cidrs.sort(key=lambda x: (x[0], x[1]))
    out = ['VALID ' + str(len(cidrs))]
    for addr, pref in cidrs:
        out.append(ip_to_str(addr) + '/' + str(pref))
    out.append('INVALID ' + str(invalid))
    sys.stdout.write('\n'.join(out) + '\n')

