import sys

def parse_time(s):
    if len(s) != 5 or s[2] != ':':
        return None
    hh = s[:2]
    mm = s[3:]
    if not (hh.isdigit() and mm.isdigit()):
        return None
    h = int(hh)
    m = int(mm)
    if h < 0 or h > 23 or m < 0 or m > 59:
        return None
    return h * 60 + m

def fmt(t):
    return f"{t // 60:02d}:{t % 60:02d}"

def main():
    lines = [line.strip() for line in sys.stdin.read().splitlines() if line.strip()]
    if not lines:
        print("NONE")
        return

    header = lines[0].split()
    if len(header) != 3:
        print("NONE")
        return
    work_start = parse_time(header[0])
    work_end = parse_time(header[1])
    try:
        minimum = int(header[2])
    except ValueError:
        print("NONE")
        return
    if work_start is None or work_end is None or work_end <= work_start or minimum < 0:
        print("NONE")
        return

    busy = []
    for line in lines[1:]:
        parts = line.split()
        if len(parts) != 2:
            continue
        s = parse_time(parts[0])
        e = parse_time(parts[1])
        if s is None or e is None or e <= s:
            continue
        s = max(s, work_start)
        e = min(e, work_end)
        if e > s:
            busy.append((s, e))

    busy.sort()
    merged = []
    for s, e in busy:
        if not merged or s > merged[-1][1]:
            merged.append([s, e])
        else:
            if e > merged[-1][1]:
                merged[-1][1] = e

    result = []
    cursor = work_start
    for s, e in merged:
        if s > cursor and s - cursor >= minimum:
            result.append(f"{fmt(cursor)} {fmt(s)}")
        if e > cursor:
            cursor = e
    if work_end > cursor and work_end - cursor >= minimum:
        result.append(f"{fmt(cursor)} {fmt(work_end)}")

    if result:
        print("\n".join(result))
    else:
        print("NONE")

