    if len(first) != 2:
        invalid()
    try:
        n = int(first[0])
        m = int(first[1])
    except ValueError:
        invalid()
    if n < 0 or m < 0:
        invalid()
    if len(data) < 1 + n + m:
        invalid()
    extra = data[1 + n + m:]
    if any(line.strip() != '' for line in extra):
        invalid()

    names = []
    seen = set()
    for i in range(n):
        parts = data[1 + i].split()
        if len(parts) != 1 or not NAME_RE.match(parts[0]):
            invalid()
        if parts[0] in seen:
            invalid()
        seen.add(parts[0])
        names.append(parts[0])

    adj = {name: [] for name in names}
    indeg = {name: 0 for name in names}
    edge_seen = set()
    for j in range(m):
        parts = data[1 + n + j].split()
        if len(parts) != 2:
            invalid()
        comp, dep = parts
        if comp not in seen or dep not in seen:
            invalid()
        if (dep, comp) not in edge_seen:
            edge_seen.add((dep, comp))
            adj[dep].append(comp)
            indeg[comp] += 1

    heap = [name for name in names if indeg[name] == 0]
    heapq.heapify(heap)
    order = []
    indeg_work = dict(indeg)
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg_work[v] -= 1
            if indeg_work[v] == 0:
                heapq.heappush(heap, v)

    if len(order) == n:
        sys.stdout.write('ORDER\n')
        for name in order:
            sys.stdout.write(name + '\n')
        return

    # Tarjan SCCs to report only nodes that are actually in cycles.
    index = 0
    stack = []
    onstack = set()
    indices = {}
    low = {}
    cyclic = []

    sys.setrecursionlimit(max(1000, n * 2 + 10))

    def strongconnect(v):
        nonlocal index
        indices[v] = index
        low[v] = index
        index += 1
        stack.append(v)
        onstack.add(v)
        for w in adj[v]:
            if w not in indices:
                strongconnect(w)
                low[v] = min(low[v], low[w])
            elif w in onstack:
                low[v] = min(low[v], indices[w])
        if low[v] == indices[v]:
            comp = []
            while True:
                w = stack.pop()
                onstack.remove(w)
                comp.append(w)
                if w == v:
                    break
            if len(comp) > 1:
                cyclic.extend(comp)
            else:
                only = comp[0]
                if only in adj[only]:
                    cyclic.append(only)

    for name in names:
        if name not in indices:
            strongconnect(name)

    sys.stdout.write('CYCLE\n')
    for name in sorted(cyclic):
