import sys
import csv
import io
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

HEADER = "employee_id\temployee_name\ttotal_hours\tbillable_hours\tutilization_pct"

def q(value, places):
    return value.quantize(Decimal(places), rounding=ROUND_HALF_UP)

def main():
    data = sys.stdin.read()
    print(HEADER)
    if data == "":
        return

    reader = csv.DictReader(io.StringIO(data))
    required = {"employee_id", "employee_name", "hours", "billable"}
    if not reader.fieldnames or not required.issubset(set(reader.fieldnames)):
        return

    employees = {}
    for row in reader:
        try:
            emp_id = row.get("employee_id")
            name = row.get("employee_name")
            hours_text = row.get("hours")
            billable_text = row.get("billable")
        except AttributeError:
            continue

        if emp_id is None or name is None or hours_text is None or billable_text is None:
            continue
        if emp_id == "" or name == "":
            continue

        try:
            hours = Decimal(hours_text.strip())
        except (InvalidOperation, AttributeError):
            continue
        if hours < 0:
            continue

        b = billable_text.strip().lower()
        if b == "yes":
            billable_hours = hours
        elif b == "no":
            billable_hours = Decimal("0")
        else:
            continue

        if emp_id not in employees:
            employees[emp_id] = {"name": name, "total": Decimal("0"), "billable": Decimal("0")}
        employees[emp_id]["total"] += hours
        employees[emp_id]["billable"] += billable_hours

    ordered = sorted(employees.items(), key=lambda item: (-item[1]["total"], item[0]))
    for emp_id, info in ordered:
        total = info["total"]
        billable = info["billable"]
        if total == 0:
            util = Decimal("0")
        else:
            util = (billable / total) * Decimal("100")
        print(f"{emp_id}\t{info['name']}\t{q(total, '0.01')}\t{q(billable, '0.01')}\t{q(util, '0.1')}")

