    except ValueError:
        return

    raw = {}
    for line in data[1:1+n]:
        if "=" not in line:
            continue
        key, value = line.split("=", 1)
        raw[key] = value

    memo = {}

    def resolve_key(key, stack):
        if key in memo:
            return memo[key]
        if key in stack:
            return ""
        if key not in raw:
            return ""
        stack.add(key)
        value = resolve_text(raw[key], stack)
        stack.remove(key)
        memo[key] = value
        return value

    def resolve_text(text, stack):
        def repl(match):
            name = match.group(1)
            has_default = match.group(2) is not None
            default = match.group(3) if has_default else ""
            if name in raw:
                return resolve_key(name, stack)
            return default if has_default else ""
        return pattern.sub(repl, text)

    out = []
    for key in sorted(raw.keys()):
        out.append(f"{key}={resolve_key(key, set())}")
    sys.stdout.write("\n".join(out))
