def valid_name(s):
    if not s:
        return False
    first = s[0]
    if not (first == '_' or first.isalpha()):
        return False
    for ch in s[1:]:
        if not (ch == '_' or ch.isalpha() or ch.isdigit()):
            return False
    return True


def expand_text(text, env, stack):
    out = []
    i = 0
    while i < len(text):
        if text.startswith('${', i):
            end = text.find('}', i + 2)
            if end == -1:
                out.append(text[i:])
                break
            inner = text[i + 2:end]
            if ':-' in inner:
                name, default = inner.split(':-', 1)
                has_default = True
            else:
                name, default = inner, ''
                has_default = False
            if valid_name(name):
                if name in env:
                    out.append(resolve(name, env, stack))
                elif has_default:
                    out.append(expand_text(default, env, stack))
                else:
                    out.append('')
            else:
                out.append(text[i:end + 1])
            i = end + 1
        else:
            out.append(text[i])
            i += 1
    return ''.join(out)


def resolve(name, env, stack):
    if name not in env:
        return ''
    if name in stack:
        return ''
    stack.add(name)
    ans = expand_text(env[name], env, stack)
    stack.remove(name)
    return ans


