import sys


def parse_ip(s):
    parts = s.split('.')
    if len(parts) != 4:
        return None
    nums = []
    for p in parts:
        if p == '' or not p.isdigit():
            return None
        v = int(p)
        if v < 0 or v > 255:
            return None
        nums.append(v)
    return (((nums[0] * 256) + nums[1]) * 256 + nums[2]) * 256 + nums[3]


def ip_to_str(v):
    a = v // (256 ** 3)
    v %= 256 ** 3
    b = v // (256 ** 2)
    v %= 256 ** 2
    c = v // 256
    d = v % 256
    return f"{a}.{b}.{c}.{d}"


def expand_expr(expr):
    expr = expr.strip()
    if expr == '':
        return None
    if '/' in expr:
        if expr.count('/') != 1:
            return None
        ip_s, pre_s = expr.split('/')
        if pre_s == '' or not pre_s.isdigit():
            return None
        prefix = int(pre_s)
        if prefix < 24 or prefix > 32:
            return None
        ip = parse_ip(ip_s.strip())
        if ip is None:
            return None
        size = 1 << (32 - prefix)
        base = (ip // size) * size
        return range(base, base + size)
    if '-' in expr:
        if expr.count('-') != 1:
            return None
        left, right = expr.split('-')
        left = left.strip()
        right = right.strip()
        start_ip = parse_ip(left)
        if start_ip is None or right == '' or not right.isdigit():
            return None
        end_oct = int(right)
        if end_oct < 0 or end_oct > 255:
            return None
        start_oct = start_ip % 256
        if end_oct < start_oct:
            return None
        base = start_ip - start_oct
        return range(start_ip, base + end_oct + 1)
    ip = parse_ip(expr)
    if ip is None:
        return None
    return range(ip, ip + 1)


