        if not (start <= ts <= end):
            continue
        if status < 500 or status > 599:
            continue
        norm_path = path.split('?', 1)[0]
        count, total = totals.get(norm_path, (0, 0))
        totals[norm_path] = (count + 1, total + byte_count)

    if not totals:
        sys.stdout.write("NONE\n")
        return
    rows = sorted(totals.items(), key=lambda item: (-item[1][0], item[0]))
    out = []
    for path, (count, total) in rows:
        out.append(f"{path} {count} {total}")
    sys.stdout.write("\n".join(out) + "\n")

