import sys
import ipaddress


def parse_ports(text):
    if text == "":
        return None
    ranges = []
    for part in text.split(','):
        if part == "":
            return None
        if '-' in part:
            pieces = part.split('-')
            if len(pieces) != 2 or pieces[0] == "" or pieces[1] == "":
                return None
            try:
                a = int(pieces[0])
                b = int(pieces[1])
            except ValueError:
                return None
            if a < 0 or b < 0 or a > 65535 or b > 65535 or a > b:
                return None
            ranges.append((a, b))
        else:
            try:
                p = int(part)
            except ValueError:
                return None
            if p < 0 or p > 65535:
                return None
            ranges.append((p, p))
    return ranges


def parse_target(text):
    try:
        if '/' in text:
            return ipaddress.IPv4Network(text, strict=True)
        return ipaddress.IPv4Network(text + '/32', strict=True)
    except ValueError:
        return None


def parse_rule(line):
    fields = line.strip().split()
    if len(fields) != 3:
        return None
    action, target_text, ports_text = fields
    if action not in ('ALLOW', 'DENY'):
        return None
    net = parse_target(target_text)
    if net is None:
        return None
    ports = parse_ports(ports_text)
    if ports is None:
        return None
    return (action, net, ports)


def port_matches(port, ranges):
    for a, b in ranges:
        if a <= port <= b:
            return True
    return False


def main():
    data = sys.stdin.read().splitlines()
    idx = 0
    rules = []
    try:
        n = int(data[idx].strip())
        idx += 1
    except Exception:
        return
    for _ in range(n):
        if idx >= len(data):
            line = ''
        else:
            line = data[idx]
        idx += 1
        r = parse_rule(line)
        if r is not None:
            rules.append(r)
    try:
        q = int(data[idx].strip())
        idx += 1
    except Exception:
        return
    out = []
    for _ in range(q):
        if idx >= len(data):
            line = ''
        else:
            line = data[idx]
        idx += 1
        fields = line.strip().split()
        result = 'DENY'
        if len(fields) == 2:
            ip_text, port_text = fields
            try:
                ip = ipaddress.IPv4Address(ip_text)
                port = int(port_text)
                if port < 0 or port > 65535:
                    raise ValueError()
                for action, net, ranges in rules:
                    if ip in net and port_matches(port, ranges):
                        result = action
            except ValueError:
                result = 'DENY'
        out.append(result)
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))


