    main()

import sys

lines = sys.stdin.read().splitlines()
if not lines:
    n = 0
    event_lines = []
else:
    first_idx = None
    for i, line in enumerate(lines):
        if line.strip() != "":
            first_idx = i
            break
    if first_idx is None:
        n = 0
        event_lines = []
    else:
        try:
            n = int(lines[first_idx].strip())
            if n < 0:
                n = 0
        except ValueError:
            n = 0
        event_lines = lines[first_idx + 1:first_idx + 1 + n]

jobs = {}          # job_id -> state
job_order = []     # accepted ADD order
workers = {}       # worker_id -> running job_id or None
ok_count = 0
fail_count = 0
out = []

for raw in event_lines:
    parts = raw.split()
    if not parts:
        continue
    cmd = parts[0]
    if cmd == "WORKER":
        if len(parts) != 2:
            continue
        wid = parts[1]
        if wid not in workers:
            workers[wid] = None
    elif cmd == "ADD":
        if len(parts) != 2:
            continue
        jid = parts[1]
        if jid not in jobs:
            jobs[jid] = "pending"
            job_order.append(jid)
    elif cmd == "CANCEL":
        if len(parts) != 2:
            continue
        jid = parts[1]
        if jobs.get(jid) == "pending":
            jobs[jid] = "canceled"
    elif cmd == "TAKE":
        if len(parts) != 2:
            continue
        wid = parts[1]
        if wid not in workers:
            out.append(f"TAKE {wid} UNKNOWN")
        elif workers[wid] is not None:
            out.append(f"TAKE {wid} BUSY")
        else:
            chosen = None
            for jid in job_order:
                if jobs.get(jid) == "pending":
                    chosen = jid
                    break
            if chosen is None:
                out.append(f"TAKE {wid} NONE")
            else:
                jobs[chosen] = "running"
                workers[wid] = chosen
                out.append(f"TAKE {wid} {chosen}")
    elif cmd == "DONE":
        if len(parts) != 3:
            continue
        wid = parts[1]
        result = parts[2]
        if wid in workers and workers[wid] is not None:
            jid = workers[wid]
            jobs[jid] = "done"
            workers[wid] = None
            if result == "OK":
                ok_count += 1
            else:
                fail_count += 1
    else:
        continue

pending = [jid for jid in job_order if jobs.get(jid) == "pending"]
running_pairs = []
for wid in sorted(workers):
    if workers[wid] is not None:
        running_pairs.append(f"{wid}:{workers[wid]}")
canceled_count = sum(1 for jid in job_order if jobs.get(jid) == "canceled")

out.append("PENDING " + str(len(pending)) + (" " + " ".join(pending) if pending else ""))
out.append("RUNNING " + str(len(running_pairs)) + (" " + " ".join(running_pairs) if running_pairs else ""))
out.append(f"DONE {ok_count} {fail_count}")
out.append(f"CANCELED {canceled_count}")

sys.stdout.write("\n".join(out) + "\n")

import sys


def parse_ints(line, expected):
    parts = line.strip().split()
    if len(parts) != expected:
        return None
    vals = []
    for p in parts:
        try:
            vals.append(int(p))
        except ValueError:
            return None
    return vals


def main():
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        print("ERROR")
        return

    first = parse_ints(data[0], 3)
    if first is None:
        print("ERROR")
        return
    start, end, width = first
    if width <= 0 or end <= start or (end - start) % width != 0:
        print("ERROR")
        return

    n_line = parse_ints(data[1], 1)
    if n_line is None:
        print("ERROR")
        return
    n = n_line[0]
    if n < 0 or len(data) != n + 2:
        print("ERROR")
        return

    bucket_count = (end - start) // width
    totals = [0] * bucket_count
    counts = [0] * bucket_count

    for i in range(n):
        rec = parse_ints(data[i + 2], 3)
        if rec is None:
            print("ERROR")
            return
        ts, latency, req_count = rec
        if start <= ts < end:
            idx = (ts - start) // width
            totals[idx] += latency
            counts[idx] += req_count

    out = ["bucket_start,bucket_end,total_latency_ms,request_count,avg_latency_ms"]
    for idx in range(bucket_count):
        b_start = start + idx * width
        b_end = b_start + width
        if counts[idx] == 0:
            avg = "NA"
        else:
            avg = str(totals[idx] // counts[idx])
        out.append(f"{b_start},{b_end},{totals[idx]},{counts[idx]},{avg}")
    sys.stdout.write("\n".join(out) + "\n")


