import sys


def valid_name(s):
    if not s:
        return False
    first = s[0]
    if not (first == '_' or ('a' <= first <= 'z')):
        return False
    for ch in s[1:]:
        if not (ch == '_' or ('a' <= ch <= 'z') or ('0' <= ch <= '9')):
            return False
    return True


def nonneg_int(s):
    if s == "":
        return False
    for ch in s:
        if not ('0' <= ch <= '9'):
            return False
    return True


def valid_value(s):
    if s == "":
        return False
    for ch in s:
        if ch.isspace() or ch == '=':
            return False
    return True


def error(n):
    print(f"ERROR line {n}")
    return


def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return error(1)
    if not nonneg_int(data[0]):
        return error(1)
