    idx = 1
    merged = {}
    for _ in range(layers):
        if idx >= len(data):
            return error(idx + 1)
        header = data[idx]
        parts = header.split(' ')
        if len(parts) != 2 or not valid_name(parts[0]) or not nonneg_int(parts[1]):
            return error(idx + 1)
