import sys


def parse_count(line):
    if line == "" or not line.isdigit():
        return None
    return int(line)


def read_snapshot(lines, idx):
    if idx >= len(lines):
        return None, idx
    count = parse_count(lines[idx])
    if count is None:
        return None, idx
    idx += 1
    if idx + count > len(lines):
        return None, idx
    data = {}
    for _ in range(count):
        line = lines[idx]
        idx += 1
        if line.count("\t") != 1:
            return None, idx
        key, value = line.split("\t", 1)
        if key == "":
            return None, idx
        data[key] = value
    return data, idx


def main():
    text = sys.stdin.read()
    lines = text.splitlines()
    old, idx = read_snapshot(lines, 0)
    if old is None:
        sys.stdout.write("ERROR\n")
        return
    new, idx = read_snapshot(lines, idx)
    if new is None or idx != len(lines):
        sys.stdout.write("ERROR\n")
        return

    added = sorted(k for k in new if k not in old)
    removed = sorted(k for k in old if k not in new)
    changed = sorted(k for k in old if k in new and old[k] != new[k])

    out = []
    out.append(f"ADDED {len(added)}")
    for k in added:
        out.append(k + "\t" + new[k])
    out.append(f"REMOVED {len(removed)}")
    for k in removed:
        out.append(k + "\t" + old[k])
    out.append(f"CHANGED {len(changed)}")
    for k in changed:
        out.append(k + "\t" + old[k] + "\t" + new[k])
    sys.stdout.write("\n".join(out) + "\n")


