import sys

def render(line, vars_):
    out = []
    i = 0
    n = len(line)
    while i < n:
        if line.startswith('\\{{', i):
            out.append('{{')
            i += 3
        elif line.startswith('{{', i):
            j = line.find('}}', i + 2)
            if j == -1:
                out.append(line[i:])
                break
            name = line[i + 2:j]
            out.append(vars_.get(name, ''))
            i = j + 2
        else:
            out.append(line[i])
            i += 1
    return ''.join(out)

def main():
    data = sys.stdin.read().splitlines()
    pos = 0
    if pos >= len(data):
        return
    n = int(data[pos])
    pos += 1
    vars_ = {}
    for _ in range(n):
        line = data[pos]
        pos += 1
        if '=' in line:
            name, value = line.split('=', 1)
        else:
            name, value = line, ''
        vars_[name] = value
    m = int(data[pos])
    pos += 1
    results = []
    for _ in range(m):
        line = data[pos]
        pos += 1
        results.append(render(line, vars_))
