import sys

def valid_pattern(p):
    parts = p.split('.')
    for i, part in enumerate(parts):
        if part == '**' and i != len(parts) - 1:
            return False
    return True

def match_score(pattern, perm):
    pp = pattern.split('.')
    qq = perm.split('.')
    score = 0
    i = 0
    while i < len(pp):
        token = pp[i]
        if token == '**':
            return score
        if i >= len(qq):
            return None
        if token == '*':
            score += 1
        elif token == qq[i]:
            score += 2
        else:
            return None
        i += 1
    if i == len(qq):
        return score
    return None

def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    pos = 0
    U, N, Q = map(int, data[pos].split())
    pos += 1
    users = {}
    for _ in range(U):
        parts = data[pos].split()
        pos += 1
        name = parts[0]
        k = int(parts[1])
        users[name] = set(parts[2:2+k])
    rules = []
    for idx in range(N):
        parts = data[pos].split()
        pos += 1
        if len(parts) != 3:
            continue
        effect, principal, pattern = parts
        if effect not in ('ALLOW', 'DENY'):
            continue
        if not valid_pattern(pattern):
            continue
        rules.append((idx, effect, principal, pattern))
    out = []
    for _ in range(Q):
        user, perm = data[pos].split()
        pos += 1
        roles = users.get(user, set())
        best_key = None
        best_effect = 'DENY'
        for idx, effect, principal, pattern in rules:
            if principal == '*':
                pscore = 1
            elif principal.startswith('role:') and principal[5:] in roles:
                pscore = 2
            elif principal.startswith('user:') and principal[5:] == user:
                pscore = 3
            else:
                continue
            spec = match_score(pattern, perm)
            if spec is None:
                continue
            deny_bit = 1 if effect == 'DENY' else 0
            key = (pscore, spec, deny_bit, idx)
            if best_key is None or key > best_key:
                best_key = key
                best_effect = effect
        out.append(best_effect)
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))

