import sys
import re
import heapq

NAME_RE = re.compile(r'^[A-Za-z0-9_.-]+$')

def main():
    data = sys.stdin.read()
    if data == "":
        sys.stdout.write("ERROR empty input\n")
        return
    lines = data.splitlines()
    if not lines:
        sys.stdout.write("ERROR empty input\n")
        return
    first = lines[0].strip()
    try:
        n = int(first)
    except ValueError:
        sys.stdout.write("ERROR malformed input\n")
        return
    if n < 0 or len(lines) != n + 1:
        sys.stdout.write("ERROR malformed input\n")
        return

    deps_by_target = {}
    malformed = False
    for line in lines[1:]:
        if line.count(':') != 1:
            malformed = True
            break
        left, right = line.split(':', 1)
        target = left.strip()
        if not target or not NAME_RE.match(target) or target in deps_by_target:
            malformed = True
            break
        deps = set()
        if right.strip():
            for token in right.split():
                if not NAME_RE.match(token):
                    malformed = True
                    break
                deps.add(token)
        if malformed:
            break
        deps_by_target[target] = deps

    if malformed:
        sys.stdout.write("ERROR malformed input\n")
        return

    declared = set(deps_by_target)
    missing = sorted({d for deps in deps_by_target.values() for d in deps if d not in declared})
    if missing:
        sys.stdout.write("ERROR unknown dependency " + missing[0] + "\n")
        return

    dependents = {t: [] for t in declared}
    indegree = {t: 0 for t in declared}
    for target, deps in deps_by_target.items():
        indegree[target] = len(deps)
        for dep in deps:
            dependents[dep].append(target)

    heap = [t for t in declared if indegree[t] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        node = heapq.heappop(heap)
        order.append(node)
        for nxt in dependents[node]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(heap, nxt)

    if len(order) != len(declared):
        sys.stdout.write("ERROR cycle\n")
        return
    if order:
        sys.stdout.write("\n".join(order) + "\n")

if __name__ == "__main__":
    main()

