import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    p = 0
    try:
        r = int(data[p]); p += 1
    except Exception:
        return
    out = []
    retryable_statuses = {"RETRY", "TIMEOUT"}
    for _ in range(r):
        if p >= len(data):
            break
        rid = data[p]; p += 1
        try:
            deadline = int(data[p]); max_attempts = int(data[p+1]); timeout = int(data[p+2])
            base = int(data[p+3]); mult = int(data[p+4]); max_back = int(data[p+5]); oc = int(data[p+6])
            p += 7
        except Exception:
            break
        outcomes = []
        for i in range(oc):
            if p + 2 < len(data):
                try:
                    dur = int(data[p]); status = data[p+1]; ra = int(data[p+2])
                except Exception:
                    dur, status, ra = 0, "RETRY", 0
                p += 3
            else:
                dur, status, ra = 0, "RETRY", 0
                p = len(data)
            outcomes.append((dur, status, ra))
        t = 0
        attempts = 0
        final = None
        while attempts < max_attempts:
            if t >= deadline:
                final = "DEADLINE"
                break
            attempts += 1
            if attempts <= len(outcomes):
                dur, status, ra = outcomes[attempts-1]
            else:
                dur, status, ra = 0, "RETRY", 0
            remaining = deadline - t
            run = min(dur, timeout, remaining)
            t += run
            if remaining <= timeout and remaining <= dur:
                final = "DEADLINE"
                break
            if timeout <= dur:
                result = "TIMEOUT"
            else:
                result = status
            if result == "OK":
                final = "OK"
                break
            if result == "FAIL":
                final = "FAIL"
                break
            if result in retryable_statuses:
                if attempts >= max_attempts:
                    final = "EXHAUSTED"
                    break
                back = base * (mult ** (attempts - 1))
                if back > max_back:
                    back = max_back
                if ra > back:
                    back = ra
                t += back
                continue
            final = result
            break
        if final is None:
            if attempts == 0 and t >= deadline:
                final = "DEADLINE"
            else:
                final = "EXHAUSTED"
        out.append(f"{rid} {attempts} {final} {t}")
    sys.stdout.write("\n".join(out))
    if out:
        sys.stdout.write("\n")

