import sys

def matches(pattern, value):
    pp = pattern.split('.')
    vv = value.split('.')
    if len(pp) != len(vv):
        return False
    for a, b in zip(pp, vv):
        if a != '*' and a != b:
            return False
    return True

def specificity(pattern):
    return sum(1 for part in pattern.split('.') if part != '*')

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    pos = 0
    R, U, P, Q = map(int, data[pos].split())
    pos += 1

    valid_roles = set()
    for _ in range(R):
        valid_roles.add(data[pos].strip())
        pos += 1

    users = {}
    for _ in range(U):
        parts = data[pos].split()
        pos += 1
        name = parts[0]
        k = int(parts[1])
        roles = set()
        for r in parts[2:2+k]:
            if r in valid_roles:
                roles.add(r)
        users[name] = roles

    policies = []
    for idx in range(P):
        effect, principal, action_pat, resource_pat = data[pos].split()
        pos += 1
        policies.append((effect, principal, action_pat, resource_pat, idx))

    out = []
    for _ in range(Q):
        user, action, resource = data[pos].split()
        pos += 1
        roles = users.get(user, set())
        best_key = None
        best_effect = 'DENY'
        for effect, principal, action_pat, resource_pat, idx in policies:
            if principal != '*' and principal not in roles:
                continue
            if not matches(action_pat, action):
                continue
            if not matches(resource_pat, resource):
                continue
            key = (1 if principal != '*' else 0, specificity(action_pat), specificity(resource_pat), idx)
            if best_key is None or key > best_key:
                best_key = key
                best_effect = effect
        out.append(best_effect)
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))

if __name__ == '__main__':
    main()

