import sys

def norm_abs(p):
    parts = []
    for seg in p.split('/'):
        if seg == '' or seg == '.':
            continue
        if seg == '..':
            if parts:
                parts.pop()
        else:
            parts.append(seg)
    return '/' + '/'.join(parts)

def filename_has_ext(name):
    i = name.rfind('.')
    return i > 0 and i < len(name) - 1

def process(req, base, default_ext):
    original = req
    p = req.replace('\\', '/')
    if p == '' or p.startswith('/') or p.endswith('/'):
        return 'REJECT ' + original
    parts = []
    for seg in p.split('/'):
        if seg == '' or seg == '.':
            continue
        if seg == '..':
            if not parts:
                return 'REJECT ' + original
            parts.pop()
        else:
            parts.append(seg)
    if not parts:
        return 'REJECT ' + original
    if not filename_has_ext(parts[-1]) and default_ext != '-':
        parts[-1] += default_ext
    rel = '/'.join(parts)
    if base == '/':
        return 'OK /' + rel
    return 'OK ' + base + '/' + rel

def main():
    data = sys.stdin.read().splitlines()
    if len(data) < 3:
        return
    base_line = data[0]
    default_ext = data[1]
    try:
        n = int(data[2])
    except ValueError:
        return
    base = norm_abs(base_line)
    out = []
    for i in range(n):
        req = data[3 + i] if 3 + i < len(data) else ''
        out.append(process(req, base, default_ext))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))

