import sys
import re

ver_re = re.compile(r'^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$')
num_re = re.compile(r'^[0-9]+$')
ident_re = re.compile(r'^[0-9A-Za-z-]+$')


def parse_version(s):
    m = ver_re.match(s)
    if not m:
        return None
    major, minor, patch = int(m.group(1)), int(m.group(2)), int(m.group(3))
    pre_s = m.group(4)
    pre = None
    if pre_s is not None:
        pre = []
        for part in pre_s.split('.'):
            if not part or not ident_re.match(part):
                return None
            if num_re.match(part):
                if len(part) > 1 and part[0] == '0':
                    return None
                pre.append((0, int(part), part))
            else:
                pre.append((1, part, part))
    return (major, minor, patch, pre)


def cmp_ver(a, b):
    for i in range(3):
        if a[i] != b[i]:
            return -1 if a[i] < b[i] else 1
    ap, bp = a[3], b[3]
    if ap is None and bp is None:
        return 0
    if ap is None:
        return 1
    if bp is None:
        return -1
    for x, y in zip(ap, bp):
        if x[0] != y[0]:
            return -1 if x[0] < y[0] else 1
        if x[1] != y[1]:
            return -1 if x[1] < y[1] else 1
    if len(ap) == len(bp):
        return 0
    return -1 if len(ap) < len(bp) else 1


def satisfies(v, op, target):
    c = cmp_ver(v, target)
    if op == '=':
        return c == 0
    if op == '!=':
        return c != 0
    if op == '>':
        return c > 0
    if op == '>=':
        return c >= 0
    if op == '<':
        return c < 0
    if op == '<=':
        return c <= 0
    return False

comp_re = re.compile(r'^(>=|<=|!=|=|>|<)\s*(\S+)$')

def parse_constraint(line):
    if line.strip() == '':
        return []
    out = []
    for part in line.split(','):
        p = part.strip()
        m = comp_re.match(p)
        if not m:
            return None
        v = parse_version(m.group(2))
        if v is None:
            return None
        out.append((m.group(1), v))
    return out


def main():
    data = sys.stdin.read().splitlines()
    pos = 0
    if pos >= len(data):
        return
    try:
        n = int(data[pos].strip())
    except Exception:
        return
    pos += 1
    versions = []
    for _ in range(n):
        if pos >= len(data):
            break
        text = data[pos].strip()
        pos += 1
        parsed = parse_version(text)
        if parsed is not None:
            versions.append((text, parsed))
    if pos >= len(data):
        return
    try:
        q = int(data[pos].strip())
    except Exception:
        return
    pos += 1
    ans = []
    for _ in range(q):
        line = data[pos] if pos < len(data) else ''
        pos += 1
        cons = parse_constraint(line)
        if cons is None:
            ans.append('INVALID')
            continue
        best = None
        for text, parsed in versions:
            ok = True
            for op, target in cons:
                if not satisfies(parsed, op, target):
                    ok = False
                    break
            if ok and (best is None or cmp_ver(parsed, best[1]) > 0):
                best = (text, parsed)
        ans.append(best[0] if best else 'NONE')
    sys.stdout.write('\n'.join(ans) + ('\n' if ans else ''))

