import sys
import re
from functools import cmp_to_key

ver_re = re.compile(r'^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$')
comp_re = re.compile(r'^(<=|>=|<|>|=)(.+)$')

def parse_version(s):
    m = ver_re.match(s)
    if not m:
        return None
    nums = (int(m.group(1)), int(m.group(2)), int(m.group(3)))
    pre_s = m.group(4)
    pre = None
    if pre_s is not None:
        pre = []
        for part in pre_s.split('.'):
            if part.isdigit():
                if len(part) > 1 and part[0] == '0':
                    return None
                pre.append((0, int(part)))
            else:
                pre.append((1, part))
    return (nums, pre)

def cmp_ver(a, b):
    if a[0] != b[0]:
        return -1 if a[0] < b[0] else 1
    ap, bp = a[1], b[1]
    if ap is None and bp is None:
        return 0
    if ap is None:
        return 1
    if bp is None:
        return -1
    for x, y in zip(ap, bp):
        if x == y:
            continue
        if x[0] != y[0]:
            return -1 if x[0] < y[0] else 1
        return -1 if x[1] < y[1] else 1
    if len(ap) == len(bp):
        return 0
    return -1 if len(ap) < len(bp) else 1

def parse_constraint(s):
    if s == '*':
        return []
    if s == '':
        return None
    out = []
    for part in s.split(','):
        if part == '':
            return None
        m = comp_re.match(part)
        if not m:
            return None
        op = m.group(1)
        v = parse_version(m.group(2))
        if v is None:
            return None
        out.append((op, v))
    return out

def ok(v, comps):
    for op, target in comps:
        c = cmp_ver(v, target)
        if op == '=' and c != 0:
            return False
        if op == '<' and not (c < 0):
            return False
        if op == '<=' and not (c <= 0):
            return False
        if op == '>' and not (c > 0):
            return False
        if op == '>=' and not (c >= 0):
            return False
    return True

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    first = data[0].split()
    if len(first) != 2:
        return
    try:
        n, q = int(first[0]), int(first[1])
    except ValueError:
        return
    packages = {}
    idx = 1
    order = 0
    for _ in range(n):
        if idx >= len(data):
            break
        line = data[idx]
        idx += 1
        parts = line.split()
        if len(parts) != 2:
            continue
        pkg, vs = parts
        pv = parse_version(vs)
        if pv is None:
            continue
        packages.setdefault(pkg, []).append((pv, order, vs))
        order += 1
    ans = []
    for _ in range(q):
        if idx >= len(data):
            line = ''
        else:
            line = data[idx]
        idx += 1
        if ' ' not in line:
            ans.append('INVALID')
            continue
        pkg, cons = line.split(' ', 1)
        comps = parse_constraint(cons)
        if comps is None:
            ans.append('INVALID')
            continue
        best = None
        for pv, ordv, vs in packages.get(pkg, []):
            if not ok(pv, comps):
                continue
            if best is None or cmp_ver(pv, best[0]) > 0:
                best = (pv, ordv, vs)
        if best is None:
            ans.append('NONE')
        else:
            ans.append(pkg + ' ' + best[2])
    sys.stdout.write('\n'.join(ans) + ('\n' if ans else ''))

if __name__ == '__main__':
    main()

import sys
import re

name_re = re.compile(r'^[A-Z_][A-Z0-9_]*$')

def valid_name(s):
    return bool(name_re.match(s))

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    try:
        n = int(data[0].strip())
    except Exception:
        return
    idx = 1
    env = {}
    for _ in range(n):
        if idx >= len(data):
            return
        line = data[idx]
        idx += 1
        if '=' not in line:
            continue
        k, v = line.split('=', 1)
        if valid_name(k):
            env[k] = v
    if idx >= len(data):
        return
    try:
        m = int(data[idx].strip())
    except Exception:
        return
    idx += 1
    queries = []
    for _ in range(m):
        if idx >= len(data):
            return
        queries.append(data[idx].strip())
        idx += 1

    memo = {}

    def resolve_var(name, stack):
        if name in memo:
            return memo[name]
        if name not in env:
            return ''
        if name in stack:
            raise ValueError('cycle')
        stack.add(name)
        val = resolve_text(env[name], stack)
        stack.remove(name)
        memo[name] = val
        return val

    def resolve_text(text, stack):
        out = []
        pos = 0
        while True:
            start = text.find('${', pos)
            if start == -1:
                out.append(text[pos:])
                break
            out.append(text[pos:start])
            end = text.find('}', start + 2)
            if end == -1:
                raise ValueError('malformed')
            content = text[start + 2:end]
            if ':-' in content:
                nm, default = content.split(':-', 1)
                if not valid_name(nm):
                    raise ValueError('malformed')
                got = resolve_var(nm, stack)
                out.append(default if got == '' else got)
            else:
                nm = content
                if not valid_name(nm):
                    raise ValueError('malformed')
                out.append(resolve_var(nm, stack))
            pos = end + 1
        return ''.join(out)

    lines = []
    for q in queries:
        try:
            if not valid_name(q):
                raise ValueError('bad query')
            ans = resolve_var(q, set())
        except Exception:
            ans = 'ERROR'
        lines.append(q + '\t' + ans)
    sys.stdout.write('\n'.join(lines) + ('\n' if lines else ''))

if __name__ == '__main__':
    main()

import sys


def read_count(lines, idx):
    if idx >= len(lines):
        return 0, idx
    try:
        n = int(lines[idx].strip())
    except ValueError:
        n = 0
    return max(0, n), idx + 1


def parse_listing(lines, idx, count):
    listing = {}
    end = min(len(lines), idx + count)
    for i in range(idx, end):
        parts = lines[i].strip().split()
        if len(parts) != 3:
            continue
        host, port_text, service = parts
        try:
            port = int(port_text)
        except ValueError:
            continue
        if port < 1 or port > 65535:
            continue
        listing[(host, port)] = service
    return listing, idx + count


def main():
    lines = sys.stdin.read().splitlines()
    idx = 0
    n, idx = read_count(lines, idx)
    old, idx = parse_listing(lines, idx, n)
    m, idx = read_count(lines, idx)
    new, idx = parse_listing(lines, idx, m)

    keys = sorted(set(old) | set(new), key=lambda k: (k[0], k[1]))
    out = []
    for host, port in keys:
        key = (host, port)
        in_old = key in old
        in_new = key in new
        if in_old and not in_new:
            out.append(f"REMOVED {host} {port} {old[key]} -")
        elif in_new and not in_old:
            out.append(f"ADDED {host} {port} - {new[key]}")
        elif old[key] != new[key]:
            out.append(f"CHANGED {host} {port} {old[key]} {new[key]}")

    if out:
        sys.stdout.write("\n".join(out) + "\n")
    else:
        sys.stdout.write("NO_CHANGES\n")


