import heapq


def invalid():
    sys.stdout.write("INVALID\n")


def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        invalid()
        return

    first = lines[0].split()
    if len(first) != 2:
        invalid()
        return
    try:
        n = int(first[0])
        m = int(first[1])
    except ValueError:
        invalid()
        return
    if n < 0 or m < 0:
        invalid()
        return

    if len(lines) != 1 + n + m:
        invalid()
        return

    names = []
    seen = set()
    for i in range(n):
        parts = lines[1 + i].split()
        if len(parts) != 1:
            invalid()
            return
        name = parts[0]
        if name in seen:
            invalid()
            return
        seen.add(name)
        names.append(name)

    graph = {name: [] for name in names}
    indeg = {name: 0 for name in names}
    edges = set()

    for j in range(m):
        parts = lines[1 + n + j].split()
        if len(parts) != 2:
            invalid()
            return
        service, dep = parts
        if service not in seen or dep not in seen:
            invalid()
            return
        edge = (dep, service)
        if edge not in edges:
            edges.add(edge)
            graph[dep].append(service)
            indeg[service] += 1

    heap = [name for name in names if indeg[name] == 0]
    heapq.heapify(heap)
    order = []

    while heap:
        cur = heapq.heappop(heap)
        order.append(cur)
        for nxt in graph[cur]:
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                heapq.heappush(heap, nxt)

    if len(order) != n:
        sys.stdout.write("CYCLE\n")
        return

    sys.stdout.write("ORDER\n")
    for name in order:
        sys.stdout.write(name + "\n")


