import sys
import heapq


def parse_nonneg(s):
    try:
        v = int(s)
    except Exception:
        return None
    if v < 0:
        return None
    return v


def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    try:
        n = int(data[0].strip())
    except Exception:
        return
    if n < 0:
        return

    active = {}
    heap = []
    out = []

    def expire(now):
        while heap and heap[0][0] <= now:
            exp, key = heapq.heappop(heap)
            if active.get(key) == exp:
                del active[key]

    for line in data[1:1 + n]:
        parts = line.split()
        if not parts:
            continue
        op = parts[0]

        if op == "PUT":
            if len(parts) != 4:
                continue
            t = parse_nonneg(parts[1])
            ttl = parse_nonneg(parts[3])
            key = parts[2]
            if t is None or ttl is None or key == "":
                continue
            expire(t)
            exp = t + ttl
            active[key] = exp
            heapq.heappush(heap, (exp, key))

        elif op == "TOUCH":
            if len(parts) != 4:
                continue
            t = parse_nonneg(parts[1])
            ttl = parse_nonneg(parts[3])
            key = parts[2]
            if t is None or ttl is None or key == "":
                continue
            expire(t)
            if key in active:
                exp = t + ttl
                active[key] = exp
                heapq.heappush(heap, (exp, key))

        elif op == "GET":
            if len(parts) != 3:
                continue
            t = parse_nonneg(parts[1])
            key = parts[2]
            if t is None or key == "":
                continue
            expire(t)
            out.append("HIT" if key in active else "MISS")

        elif op == "DEL":
            if len(parts) != 3:
                continue
            t = parse_nonneg(parts[1])
            key = parts[2]
            if t is None or key == "":
                continue
            expire(t)
            active.pop(key, None)

        elif op == "COUNT":
            if len(parts) != 2:
                continue
            t = parse_nonneg(parts[1])
            if t is None:
                continue
            expire(t)
            out.append(str(len(active)))

    sys.stdout.write("\n".join(out))
    if out:
        sys.stdout.write("\n")


