import sys


def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    try:
        first = data[0].split()
        if len(first) != 3:
            print("ERROR 0")
            return
        capacity = int(first[0])
        default_ttl = int(first[1])
        q = int(first[2])
        if capacity < 0 or q < 0:
            print("ERROR 0")
            return
    except Exception:
        print("ERROR 0")
        return

    cache = {}  # key -> [value, expires_at, recent_order]
    order = 0
    last_time = None
    out = []

    def purge(now):
        expired = [k for k, v in cache.items() if v[1] <= now]
        for k in expired:
            del cache[k]

    def evict_if_needed():
        while len(cache) > capacity:
            victim = min(cache.items(), key=lambda item: item[1][2])[0]
            del cache[victim]

    for i in range(1, q + 1):
        line = data[i] if i < len(data) else ""
        parts = line.split()
        valid = True
        try:
            if len(parts) < 2:
                valid = False
            else:
                t = int(parts[0])
                cmd = parts[1]
                if last_time is not None and t < last_time:
                    valid = False
        except Exception:
            valid = False

        if not valid:
            out.append(f"ERROR {i}")
            continue

        if cmd == "PUT":
            if len(parts) not in (4, 5):
                out.append(f"ERROR {i}")
                continue
            key = parts[2]
            value = parts[3]
            try:
                ttl = int(parts[4]) if len(parts) == 5 else default_ttl
            except Exception:
                out.append(f"ERROR {i}")
                continue
            purge(t)
            last_time = t
            order += 1
            if ttl <= 0 or capacity == 0:
                cache.pop(key, None)
            else:
                cache[key] = [value, t + ttl, order]
                evict_if_needed()
        elif cmd == "GET":
            if len(parts) != 3:
                out.append(f"ERROR {i}")
                continue
            key = parts[2]
            purge(t)
            last_time = t
            if key in cache:
                order += 1
                cache[key][2] = order
                out.append(f"HIT {key} {cache[key][0]}")
            else:
                out.append(f"MISS {key}")
        elif cmd == "DELETE":
            if len(parts) != 3:
                out.append(f"ERROR {i}")
                continue
            key = parts[2]
            purge(t)
            last_time = t
            if key in cache:
                del cache[key]
                out.append(f"DELETED {key}")
            else:
                out.append(f"MISS {key}")
        else:
            out.append(f"ERROR {i}")

    out.append(f"SIZE {len(cache)}")
    if cache:
        for key, rec in sorted(cache.items(), key=lambda item: item[1][2]):
            out.append(f"{key} {rec[0]} {rec[1]}")
    else:
        out.append("EMPTY")
    sys.stdout.write("\n".join(out) + "\n")


