def split_suffix(s):
    q = s.find('?')
    h = s.find('#')
    positions = [x for x in (q, h) if x != -1]
    if not positions:
        return s, ''
    i = min(positions)
    return s[:i], s[i:]


def parse_absolute(u):
    p = u.find('://')
    scheme = u[:p].lower()
    rest = u[p+3:]
    path_start = len(rest)
    for ch in ['/', '?', '#']:
        x = rest.find(ch)
        if x != -1 and x < path_start:
            path_start = x
    host = rest[:path_start].lower()
    tail = rest[path_start:]
    path, suffix = split_suffix(tail)
    if path == '':
        path = '/'
    return scheme, host, path, suffix


def normalize_path(path):
    if path == '':
        return '/'
    trailing = path.endswith('/') or path.endswith('/.') or path.endswith('/..')
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            continue
        stack.append(part)
    out = '/' + '/'.join(stack)
    if trailing and out != '/':
        out += '/'
    return out


def base_directory(path):
    if path.endswith('/'):
        return path
    i = path.rfind('/')
    if i == -1:
        return '/'
    return path[:i+1]


def resolve(base, ref):
    bs, bh, bp, _ = parse_absolute(base)
    low = ref.lower()
    if low.startswith('http://') or low.startswith('https://'):
        s, h, p, suf = parse_absolute(ref)
        return s + '://' + h + normalize_path(p) + suf
    if ref.startswith('//'):
        rest = ref[2:]
        path_start = len(rest)
        for ch in ['/', '?', '#']:
            x = rest.find(ch)
            if x != -1 and x < path_start:
                path_start = x
        h = rest[:path_start].lower()
        tail = rest[path_start:]
        p, suf = split_suffix(tail)
        if p == '':
            p = '/'
        return bs + '://' + h + normalize_path(p) + suf
    p, suf = split_suffix(ref)
    if ref == '' or (p == '' and suf != ''):
        combined = bp
    elif p.startswith('/'):
        combined = p
    else:
        combined = base_directory(bp) + p
    return bs + '://' + bh + normalize_path(combined) + suf


def main():
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        return
    base = data[0]
    n = int(data[1])
    refs = data[2:2+n]
    out = [resolve(base, r) for r in refs]
    sys.stdout.write('\n'.join(out))
    if out:
        sys.stdout.write('\n')


if __name__ == '__main__':
    main()

import sys


def bad_first():
    print("INVALID_INPUT")


def valid_name(s):
    if not (1 <= len(s) <= 60):
        return False
    for ch in s:
        if ch.isalpha() or ch.isdigit() or ch in " &.-":
            continue
        return False
    return True


def valid_id(s):
    return len(s) >= 5 and len(s) <= 9 and s[0] == 'V' and s[1:].isdigit()


def valid_country(s):
    return len(s) == 2 and s.isalpha() and s.upper() == s


def valid_email(s):
    if s.count('@') != 1:
        return False
    local, domain = s.split('@')
    if not local or not domain:
        return False
    dot = domain.find('.')
    if dot <= 0 or dot == len(domain) - 1:
        return False
    return True


def main():
    data = sys.stdin.read().splitlines()
    if not data:
        bad_first()
        return
    try:
        n = int(data[0].strip())
    except ValueError:
        bad_first()
        return
    if n < 0 or n > 10000:
        bad_first()
        return

    valid = []
    invalid = []
    seen = set()
    for i in range(n):
        line = data[i + 1] if i + 1 < len(data) else ""
        line_no = i + 1
        parts = line.split('|')
        if len(parts) != 5:
            invalid.append((line_no, "FIELD_COUNT"))
            continue
        vid, name, country, email, active = [p.strip() for p in parts]
        name = ' '.join(name.split())
        email = email.lower()
        active_key = active.lower()

        if not valid_id(vid):
            reason = "BAD_ID"
        elif not valid_name(name):
            reason = "BAD_NAME"
        elif not valid_country(country):
            reason = "BAD_COUNTRY"
        elif not valid_email(email):
            reason = "BAD_EMAIL"
        elif active_key not in {"true", "false", "yes", "no", "1", "0"}:
            reason = "BAD_ACTIVE"
        elif vid in seen:
            reason = "DUPLICATE_ID"
        else:
            norm_active = "true" if active_key in {"true", "yes", "1"} else "false"
            seen.add(vid)
            valid.append((vid, name, country, email, norm_active))
            continue
        invalid.append((line_no, reason))

    valid.sort(key=lambda r: r[0])
    out = ["VALID " + str(len(valid))]
    out += ['|'.join(r) for r in valid]
    out.append("INVALID " + str(len(invalid)))
    out += [str(no) + "|" + reason for no, reason in invalid]
    sys.stdout.write('\n'.join(out) + '\n')


if __name__ == "__main__":
    main()

import sys
from datetime import datetime, timedelta

FMT = "%Y-%m-%d %H:%M"

def parse_dt(s):
    return datetime.strptime(s.strip(), FMT)

def parse_hhmm(s):
    h, m = s.split(":")
    return int(h) * 60 + int(m)

def overlap_minutes(a_start, a_end, b_start, b_end):
    s = max(a_start, b_start)
    e = min(a_end, b_end)
    if e <= s:
        return 0
    return int((e - s).total_seconds() // 60)

lines = sys.stdin.read().splitlines()
if len(lines) < 10:
    print(0)
    sys.exit(0)

range_start = parse_dt(lines[0])
range_end = parse_dt(lines[1])
if range_end <= range_start:
    print(0)
    sys.exit(0)

weekly = []
for i in range(7):
    entry = lines[2 + i].strip()
    if entry == "CLOSED":
        weekly.append(None)
    else:
        left, right = entry.split("-")
        weekly.append((parse_hhmm(left), parse_hhmm(right)))

n = int(lines[9].strip())
busy = []
for line in lines[10:10 + n]:
    parts = line.split()
    start = parse_dt(parts[0] + " " + parts[1])
    end = parse_dt(parts[2] + " " + parts[3])
    if end > start:
        s = max(start, range_start)
        e = min(end, range_end)
        if e > s:
            busy.append((s, e))

busy.sort()
merged = []
for s, e in busy:
    if not merged or s > merged[-1][1]:
        merged.append([s, e])
    else:
        if e > merged[-1][1]:
            merged[-1][1] = e

total = 0
cur_day = range_start.date()
last_day = range_end.date()
one_day = timedelta(days=1)
while cur_day <= last_day:
    w = weekly[cur_day.weekday()]
    if w is not None:
        start_min, end_min = w
        if end_min > start_min:
            midnight = datetime.combine(cur_day, datetime.min.time())
            win_start = midnight + timedelta(minutes=start_min)
            win_end = midnight + timedelta(minutes=end_min)
            available = overlap_minutes(win_start, win_end, range_start, range_end)
            if available:
                clipped_start = max(win_start, range_start)
                clipped_end = min(win_end, range_end)
                blocked = 0
                for bs, be in merged:
                    if be <= clipped_start:
                        continue
                    if bs >= clipped_end:
                        break
                    blocked += overlap_minutes(clipped_start, clipped_end, bs, be)
                total += max(0, available - blocked)
    cur_day += one_day

print(total)

import sys

lines = sys.stdin.read().splitlines()

def empty(invalid):
    print(f"INVALID {invalid}")
    print("JOBS")
    print("WORKERS")

if not lines:
    empty(1)
    sys.exit(0)

try:
    n = int(lines[0])
    if n < 0 or str(n) != lines[0].strip():
        raise ValueError
except Exception:
    empty(1)
    sys.exit(0)

jobs = {}
workers = {}
invalid = 0

def ensure_worker(w):
    if w not in workers:
        workers[w] = {"ok": 0, "fail": 0, "canceled": 0, "active": None}

for i in range(n):
    if i + 1 >= len(lines):
        invalid += 1
        continue
    parts = lines[i + 1].split()
    if not parts:
        invalid += 1
        continue
    cmd = parts[0]
    ok = False
    if cmd == "ENQUEUE" and len(parts) == 3:
        jid = parts[1]
        try:
            pr = int(parts[2])
            if jid and 0 <= pr <= 100 and jid not in jobs:
                jobs[jid] = {"state": "queued", "worker": None, "result": None, "priority": pr}
                ok = True
        except Exception:
            pass
    elif cmd == "ASSIGN" and len(parts) == 3:
        wid, jid = parts[1], parts[2]
        if wid and jid in jobs and jobs[jid]["state"] == "queued":
            if wid not in workers or workers[wid]["active"] is None:
                ensure_worker(wid)
                workers[wid]["active"] = jid
                jobs[jid]["state"] = "running"
                jobs[jid]["worker"] = wid
                ok = True
    elif cmd == "COMPLETE" and len(parts) == 4:
        wid, jid, res = parts[1], parts[2], parts[3]
        if res in ("OK", "FAIL") and wid in workers and jid in jobs:
            if workers[wid]["active"] == jid and jobs[jid]["state"] == "running" and jobs[jid]["worker"] == wid:
                workers[wid]["active"] = None
                if res == "OK":
                    workers[wid]["ok"] += 1
                else:
                    workers[wid]["fail"] += 1
                jobs[jid]["state"] = "done"
                jobs[jid]["result"] = res
                jobs[jid]["worker"] = None
                ok = True
    elif cmd == "CANCEL" and len(parts) == 2:
        jid = parts[1]
        if jid in jobs and jobs[jid]["state"] in ("queued", "running"):
            if jobs[jid]["state"] == "running":
                wid = jobs[jid]["worker"]
                workers[wid]["active"] = None
                workers[wid]["canceled"] += 1
                jobs[jid]["worker"] = None
            jobs[jid]["state"] = "canceled"
            jobs[jid]["result"] = None
            ok = True
    if not ok:
        invalid += 1

out = []
out.append(f"INVALID {invalid}")
out.append("JOBS")
for jid in sorted(jobs):
    j = jobs[jid]
    worker = j["worker"] if j["worker"] is not None else "-"
    result = j["result"] if j["result"] is not None else "-"
    out.append(f"{jid} {j['state']} {worker} {result} {j['priority']}")
out.append("WORKERS")
for wid in sorted(workers):
    w = workers[wid]
    active = w["active"] if w["active"] is not None else "-"
    out.append(f"{wid} {w['ok']} {w['fail']} {w['canceled']} {active}")
print("\n".join(out))

import sys

def chunks_word(word, width):
    return [word[i:i+width] for i in range(0, len(word), width)]

def wrap_message(msg, width):
    words = msg.strip().split()
    if not words:
        return [""]
    lines = []
    cur = ""
    for word in words:
        parts = chunks_word(word, width) if len(word) > width else [word]
        for part in parts:
            if not cur:
                cur = part
            elif len(cur) + 1 + len(part) <= width:
                cur += " " + part
            else:
                lines.append(cur)
                cur = part
    if cur or not lines:
        lines.append(cur)
    return lines

def label_cell(label, width):
    if len(label) <= width:
        return label + " " * (width - len(label))
    if width <= 0:
        return ""
    return label[:width-1] + "~"

def main():
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        return
    try:
        page_width, label_width = map(int, data[0].split())
        n = int(data[1].strip())
    except Exception:
        return
    msg_width = page_width - label_width - 3
    if msg_width < 1:
        msg_width = 1
    out = []
    for raw in data[2:2+n]:
        if "\t" in raw:
            label, msg = raw.split("\t", 1)
        else:
            label, msg = raw, ""
        lab = label_cell(label, label_width)
        blank = " " * label_width
        parts = wrap_message(msg, msg_width)
        for i, part in enumerate(parts):
            out.append((lab if i == 0 else blank) + " | " + part)
    if out:
        sys.stdout.write("\n".join(out) + "\n")

if __name__ == "__main__":
    main()
